add_filter( 'woocommerce_account_menu_items', 'perfectpixel_hide_empty_downloads_tab', 30 );

function perfectpixel_hide_empty_downloads_tab( $items ) {
	if ( isset( $items['downloads'] ) && function_exists( 'WC' ) && WC()->customer && ! WC()->customer->get_downloadable_products() ) {
		unset( $items['downloads'] );
	}
	return $items;
}
